class Solution {
  public boolean isDecomposable(String s) {
    // every run of equal digits splits into 3s, plus at most one 2 overall
    boolean usedTwo = false;
    for (int i = 0; i < s.length(); ) {
      int j = i;
      while (j < s.length() && s.charAt(j) == s.charAt(i)) j++;
      int rem = (j - i) % 3;
      if (rem == 1) return false;
      if (rem == 2) {
        if (usedTwo) return false;
        usedTwo = true;
      }
      i = j;
    }
    return usedTwo;
  }
}
